// Long returns a Sleep 64-bit integer value.
func Long(v int64) Value { return opforimpl.Long(v) }

// New creates an OPFOR runtime. Console output defaults to os.Stdout, warnings
// and diagnostics to os.Stderr, and input to os.Stdin. The portable Sleep
// standard library includes live filesystem and process functions; Host is an
// extension boundary, not a sandbox for those builtins.
func New(options ...Option) (*Runtime, error) { return opforimpl.New(options...) }

// NewAccessOrderedHash creates Sleep's access-ordered hash variant (ohasha).
// Reading or replacing an existing entry moves it to the end of iteration
// order. Script-level miss and removal policies are installed separately.
func NewAccessOrderedHash() *Hash { return opforimpl.NewAccessOrderedHash() }

// NewArray returns a mutable array containing values in argument order.
func NewArray(values ...Value) *Array { return opforimpl.NewArray(values...) }

// NewCell returns a mutable cell initialized to value.
func NewCell(value Value) *Cell { return opforimpl.NewCell(value) }

// NewFileSourceResolver constructs a filesystem resolver. An empty base uses
// the process working directory at construction time. JAR and ZIP containers
// are read with Go's archive/zip package and do not require Java or CGO.
func NewFileSourceResolver(baseDirectory string) (*FileSourceResolver, error) {
	return opforimpl.NewFileSourceResolver(baseDirectory)
}

// NewHash creates an ordinary hash with Sleep-compatible key traversal order.
func NewHash() *Hash { return opforimpl.NewHash() }

// NewOrderedHash creates Sleep's insertion-ordered hash variant (ohash).
func NewOrderedHash() *Hash { return opforimpl.NewOrderedHash() }

// NewReadOnlyArray returns an array whose elements can be inspected and
// iterated but whose structure and indexed values cannot be changed.
func NewReadOnlyArray(values ...Value) *Array { return opforimpl.NewReadOnlyArray(values...) }

// NewReadOnlyHash returns a deterministic detached map wrapper. Keys and
// values can be inspected and iterated, while indexed writes affect only a
// detached scalar and structural removals are rejected. Input values are
// copied into the new hash in lexical key order.
func NewReadOnlyHash(values map[string]Value) *Hash { return opforimpl.NewReadOnlyHash(values) }

// NewScriptLoaderCache constructs an empty shared ScriptLoader compilation
// cache. Supplying it to more than one Runtime is the opt-in sharing boundary.
func NewScriptLoaderCache() *ScriptLoaderCache { return opforimpl.NewScriptLoaderCache() }

// NewSource constructs a named source unit without copying data.
func NewSource(name string, data []byte) Source { return opforimpl.NewSource(name, data) }

// Null returns Sleep's $null value.
func Null() Value { return opforimpl.Null() }

// ObjectValue wraps an opaque host object. A nil object becomes $null.
func ObjectValue(v any) Value { return opforimpl.ObjectValue(v) }

// String returns a textual Sleep string. Valid UTF-8 is mapped to the same
// UTF-16 code units a Java String would contain. Invalid UTF-8 bytes retain the
// historical OPFOR byte-string behavior; new code with binary data should use
// BinaryString so valid UTF-8 byte sequences remain distinguishable from text.
func String(v string) Value { return opforimpl.String(v) }

